import{_ as t,o,c as a,a2 as i}from"./chunks/framework.BXzK3EA4.js";const n="/assets/e109462f4e166757.BOZ1DckU.png",r="/assets/image-20221129105941832.CZrTv74i.png",c="/assets/image-20221129111128382.qE1MyH8E.png",l="/assets/image-20221129112858241.D01te_iP.png",k=JSON.parse('{"title":"Enable dynamic authentication for login Raksmart","description":"","frontmatter":{"title":"Enable dynamic authentication for login Raksmart"},"headers":[],"relativePath":"operations-knowledge-base/account-security/enable-dynamic-authentication-for-login-raksmart.md","filePath":"operations-knowledge-base/account-security/enable-dynamic-authentication-for-login-raksmart.md","lastUpdated":1794292919000}'),s={name:"operations-knowledge-base/account-security/enable-dynamic-authentication-for-login-raksmart.md"};function p(d,e,u,m,h,g){return o(),a("div",null,[...e[0]||(e[0]=[i('<p>RakSmart.com uses dynamic login password verification to enhance security.</p><p>Please take the following steps to enable dynamic login:</p><ol><li>Download and install Two-Factor Authentication (2FA) generator from Microsoft or Google.</li></ol><p>Download links: Microsoft Authenticator, Google Authenticator.</p><p>You can search “authenticator” in App Store as well.</p><p>Microsoft Authenticator is preferred. Microsoft Authenticator screenshot is attached below for your reference.</p><p><img src="'+n+'" alt=""></p><ol start="2"><li>Log onto RakSmart.com. Click on the Avatar in the top right -&gt; Security Settings -&gt; click here to enable.</li></ol><p><img src="'+r+'" alt="image-20221129105941832"></p><p>Click on Get Started -&gt; the QR code will pop up.</p><p>For the devices installed with Microsoft Authenticator, click on the + on the top right, and choose Other.</p><p>For Google Authenticator’s, click on the + on the bottom right, and choose Scan a QR Code.</p><ol><li>Use your device to scan the QR code above.</li></ol><p><img src="'+c+'" alt="image-20221129111128382"></p><ol start="2"><li><p>A dynamic verification code will be generated for your account.</p></li><li><p>Fill the code in the field marked in position ③ in the above picture and click on Submit.</p></li></ol><p>Please note that if you received a message like the one showed in the picture above after click on Submit, it means that your verification was successful. If the code is not available, please manually enter the key listed in the position ①.</p><p>Please save your Backup Code. When your mobile phone device isn’t working, you can use it to log in. The code will become invalid after login and a new one will be generated.</p><p><img src="'+l+'" alt="image-20221129112858241"></p><ol start="3"><li><p>After activation, you will need to enter dynamic verification code to log in. If your phone device isn’t working, you can use Backup Code. Please click here to use Backup Code to log in.</p></li><li><p>If dynamic verification code or Backup Code is non-functional, please contact <a href="mailto:support@raksmart.com" target="_blank" rel="noreferrer">support@raksmart.com</a> for further help.</p></li></ol>',19)])])}const _=t(s,[["render",p]]);export{k as __pageData,_ as default};
